INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"68aa0b85-4c2d-5aa0-bd77-c12416c76f9c","title":"Life Orientation · Grade 10 · Term 2: Civic responsibility and study skills · Set A","subject":"Life Orientation","grade":"Grade 10","questions":[{"question":"A class identifies unsafe litter near its school. What is a constructive civic response?","options":["Burn all waste without permission or safety checks","Ignore other people's concerns","Share unverified accusations online","Investigate safely and work with the school and relevant local services on a plan"],"correct_index":3,"explanation":"Civic participation combines evidence, safe action and cooperation. Define the problem, agree responsibilities and evaluate the outcome.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which study method best checks understanding?","options":["Close the notes, explain the idea and answer a practice question","Read the same page without testing recall","Highlight every word","Study only the night before every test"],"correct_index":0,"explanation":"Retrieval and explanation reveal gaps. Check answers and revisit the parts you cannot yet explain accurately.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why evaluate a social-media claim before sharing it?","options":["Popular posts are always accurate","Unverified claims can mislead people and harm others","Images never need context","Sharing is evidence that a claim is true"],"correct_index":1,"explanation":"Check the original source, date, evidence and context. Avoid amplifying a claim simply because it is emotional or widely repeated.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A study plan has five hours without breaks after a full school day. What is a useful improvement?","options":["Remove sleep to fit more work","Avoid all difficult subjects forever","Use manageable focused sessions with breaks and realistic priorities","Treat a missed session as failure of the whole year"],"correct_index":2,"explanation":"A sustainable plan considers attention, rest, tasks and available time. Review and adapt it rather than demanding an unrealistic schedule.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A class shares a dramatic litter-related health claim with no source to encourage cleanup. Which revision best supports responsible civic action?","options":["Keep the unverified claim because good intentions guarantee accuracy.","Add more alarming wording instead of checking it.","Verify the claim and communicate accurate evidence alongside a safe cleanup plan.","Ask learners to handle unknown hazardous waste without supervision."],"correct_index":2,"explanation":"Responsible action combines credible information with safety and appropriate support. A useful goal does not make an unsupported claim reliable or justify unsafe handling of waste.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Civic responsibility and study skills. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","lo"],"metadata":{"term":2,"focus":"Civic responsibility and study skills","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=ntp5i2bToS4%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"d5f5c8ae-bdf1-55fa-83cc-f9dd48d03611","title":"Life Orientation · Grade 10 · Term 3: Life roles, relationships and careers · Set A","subject":"Life Orientation","grade":"Grade 10","questions":[{"question":"A learner balances schoolwork, family duties and sport. What is a useful first step when demands clash?","options":["List priorities, discuss constraints and agree a workable schedule","Assume every demand can happen at the same time","Stop communicating with everyone","Give up every long-term goal immediately"],"correct_index":0,"explanation":"Life roles can compete for time. Planning and respectful discussion help negotiate realistic responsibilities and support.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What is assertive communication?","options":["Threatening others until they agree","Expressing needs clearly and respectfully while respecting others' rights","Never expressing any needs","Spreading rumours instead of talking"],"correct_index":1,"explanation":"Assertiveness differs from aggression and passivity. It combines clarity, boundaries and respect.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why research several careers before choosing school-to-work pathways?","options":["Every career has identical requirements","A single advertisement guarantees employment","Entry requirements, tasks and opportunities differ","Personal interests never matter"],"correct_index":2,"explanation":"Compare reliable information about qualifications, costs, daily work and opportunities with interests and strengths. Keep alternatives open.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A friend pressures a learner to ignore an agreed boundary. Which response is healthiest?","options":["Agree because friendship removes choice","Threaten retaliation","Assume discomfort must always be ignored","State the boundary clearly and seek trusted support if pressure continues"],"correct_index":3,"explanation":"Healthy relationships respect consent and boundaries. Support from a trusted adult or professional can help when pressure or harm persists.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A learner's career plan conflicts with family duties and transport limits. Which decision process is strongest?","options":["Choose solely by a career title's popularity.","Ignore all constraints because motivation removes them.","Compare pathways and requirements, discuss support and make a feasible schedule with alternatives.","Abandon all goals without investigating options."],"correct_index":2,"explanation":"A sound plan integrates interests with practical requirements and available support. Comparing alternatives and discussing constraints can identify workable routes rather than treating barriers as either irrelevant or final.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Life roles, relationships and careers. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","lo"],"metadata":{"term":3,"focus":"Life roles, relationships and careers","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=ntp5i2bToS4%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"c3a9f77e-63a7-510f-8248-244678b02b66","title":"Life Orientation · Grade 10 · Term 4: Lifelong learning, diversity and ethical sport · Set A","subject":"Life Orientation","grade":"Grade 10","questions":[{"question":"Why does lifelong learning matter as work changes?","options":["One qualification guarantees unchanged work forever","People may need to update skills and adapt to new opportunities","Learning ends at matric","Only unemployed people learn"],"correct_index":1,"explanation":"Technology and economic change can alter tasks and skills. Ongoing learning can support adaptation, although it cannot guarantee employment.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"What is a respectful response to different religious beliefs at school?","options":["Assume everyone shares one belief","Mock unfamiliar practices","Discuss differences without discrimination and respect others' rights","Exclude people from learning because of belief"],"correct_index":2,"explanation":"A diverse society needs respectful participation and protection of rights. Disagreement does not justify discrimination or harassment.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why is match-fixing unethical?","options":["It improves fairness for all participants","It is the same as training harder","It affects only the colour of uniforms","It undermines fair competition and trust in sporting results"],"correct_index":3,"explanation":"Manipulating results for improper advantage harms players, supporters and the integrity of sport.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"What should a learner check when investigating a qualification?","options":["Its recognition, entry requirements, costs and suitable study pathway","Only the advert's font","Whether a stranger promises a guaranteed job","Only how quickly a payment can be made"],"correct_index":0,"explanation":"Use reliable institution and qualification information. Verify legitimacy and requirements before committing time or money.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A training advert promises a recognised qualification but names no awarding body. What should a learner do before paying?","options":["Pay immediately because attractive branding proves recognition.","Assume every online course has identical recognition.","Verify the provider and qualification through credible official channels and compare the terms.","Use only testimonials supplied by the seller."],"correct_index":2,"explanation":"Recognition, provider legitimacy, costs and entry requirements need independent checking. Promotional testimonials and presentation alone cannot establish the status or value of a qualification.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Lifelong learning, diversity and ethical sport. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","lo"],"metadata":{"term":4,"focus":"Lifelong learning, diversity and ethical sport","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=ntp5i2bToS4%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"f67340bd-0c33-57f4-ae99-5c49571c0f1e","title":"English HL · Grade 10 · Term 2: Reading for evidence and inference · Set A","subject":"English HL","grade":"Grade 10","questions":[{"question":"Where does Mila arrive?","options":["At the library","At a stadium","At a hospital","At the test venue"],"correct_index":0,"explanation":"The first sentence states the location directly. A retrieval question asks for information explicitly present in the text.","stimulus":"Mila reached the library after the lights had been switched off. She looked at the book in her hand, then at the locked door. Tomorrow's test suddenly felt much closer.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Which detail most clearly shows that she cannot enter?","options":["She holds a book","The door is locked","There is a test tomorrow","She looks at the building"],"correct_index":1,"explanation":"The locked door is direct evidence that entry is blocked. The book and test explain her purpose but do not themselves prevent entry.","stimulus":"Mila reached the library after the lights had been switched off. She looked at the book in her hand, then at the locked door. Tomorrow's test suddenly felt much closer.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"What can reasonably be inferred about Mila?","options":["She has already written the test","She works as the librarian","She is concerned about preparing for the test","She is certain she will fail"],"correct_index":2,"explanation":"The final sentence suggests anxiety about limited preparation time. It does not establish her eventual result.","stimulus":"Mila reached the library after the lights had been switched off. She looked at the book in her hand, then at the locked door. Tomorrow's test suddenly felt much closer.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Which statement is an unsupported addition to the passage?","options":["Mila has a book","The library lights are off","A test is scheduled for tomorrow","Mila failed her test"],"correct_index":3,"explanation":"The passage never gives the test result. An inference must remain within what evidence reasonably supports.","stimulus":"Mila reached the library after the lights had been switched off. She looked at the book in her hand, then at the locked door. Tomorrow's test suddenly felt much closer.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"How does the final sentence affect the reader's understanding of the locked door?","options":["It proves Mila has already failed the test.","It shows the library has no books.","It turns a practical obstacle into a moment of increased test anxiety.","It establishes that the test date was changed."],"correct_index":2,"explanation":"The test feeling closer links the closed library to Mila's urgency. This emotional effect is supported, whereas a result, missing books or changed date is never stated.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Mila reached the library after the lights had been switched off. She looked at the book in her hand, then at the locked door. Tomorrow's test suddenly felt much closer."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Reading for evidence and inference. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","enhl"],"metadata":{"term":2,"focus":"Reading for evidence and inference","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Ll2-TaTJBoI%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"dfc959fc-3271-597e-ba12-de32524ef518","title":"English HL · Grade 10 · Term 3: Persuasive language and audience · Set A","subject":"English HL","grade":"Grade 10","questions":[{"question":"What is the main purpose of the text?","options":["To report a completed sports match","To persuade people to join a reading circle","To explain how electricity works","To provide a formal exam timetable"],"correct_index":1,"explanation":"The invitation, command and positive promise encourage participation. Purpose concerns what the writer wants the audience to do or think.","stimulus":"Join our Saturday reading circle. Bring one book and leave with a hundred ideas! Everyone is welcome, whether you read quickly or take your time.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Which expression is a clear exaggeration?","options":["Saturday reading circle","Bring one book","Leave with a hundred ideas","Everyone is welcome"],"correct_index":2,"explanation":"The large promise emphasises benefit rather than giving a measured count. This hyperbole adds persuasive energy.","stimulus":"Join our Saturday reading circle. Bring one book and leave with a hundred ideas! Everyone is welcome, whether you read quickly or take your time.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"What is the effect of whether you read quickly or take your time?","options":["It excludes slower readers","It gives an exact reading-speed statistic","It changes Saturday into a school day","It reassures readers with different reading speeds"],"correct_index":3,"explanation":"The inclusive wording reduces a possible barrier to joining. Explain the effect with reference to the particular audience.","stimulus":"Join our Saturday reading circle. Bring one book and leave with a hundred ideas! Everyone is welcome, whether you read quickly or take your time.","cognitive_level":{"code":"L5","label":"Appreciation","band":"higher"}},{"question":"Which verb begins an imperative in the text?","options":["Join","Ideas","Everyone","Quickly"],"correct_index":0,"explanation":"Join directly urges the reader to act. Imperatives commonly omit the subject you, which is understood.","stimulus":"Join our Saturday reading circle. Bring one book and leave with a hundred ideas! Everyone is welcome, whether you read quickly or take your time.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Is a hundred ideas best read as a precise promise? Choose the strongest evaluation.","options":["Yes; every participant is guaranteed exactly one hundred ideas.","No; the phrase proves that no ideas will be shared.","No; the exaggeration enthusiastically promotes the circle rather than measuring an exact outcome.","Yes; a precise attendance count is given."],"correct_index":2,"explanation":"The rounded, extravagant number supports persuasive enthusiasm. The passage provides no counting method or guarantee, so treating it as a literal measured promise overstates the evidence.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Join our Saturday reading circle. Bring one book and leave with a hundred ideas! Everyone is welcome, whether you read quickly or take your time."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Persuasive language and audience. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","enhl"],"metadata":{"term":3,"focus":"Persuasive language and audience","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Ll2-TaTJBoI%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"2f8ef64d-1019-5d90-a7c7-1c5ffe573c79","title":"English HL · Grade 10 · Term 4: Literary imagery and revision · Set A","subject":"English HL","grade":"Grade 10","questions":[{"question":"Which phrase uses personification?","options":["One small plant","Opening her exercise book","The classroom slept","Lindi watered it"],"correct_index":2,"explanation":"Sleeping is attributed to the classroom, giving an inanimate place a human action and creating a quiet, neglected atmosphere.","stimulus":"The classroom slept beneath a blanket of dust. At the window, one small plant leaned towards the sun. Lindi watered it before opening her exercise book.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"What does a blanket of dust suggest?","options":["Someone left a literal wool blanket","The room is outdoors","The sun has disappeared","Dust covers surfaces extensively"],"correct_index":3,"explanation":"The metaphor compares a covering of dust to a blanket. Interpret its effect rather than treating it as a literal object.","stimulus":"The classroom slept beneath a blanket of dust. At the window, one small plant leaned towards the sun. Lindi watered it before opening her exercise book.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Which detail shows an act of care?","options":["Lindi waters the plant","The dust covers the room","The classroom is described as sleeping","The window exists"],"correct_index":0,"explanation":"Watering the plant is a deliberate action that supports its life. This provides evidence for character interpretation.","stimulus":"The classroom slept beneath a blanket of dust. At the window, one small plant leaned towards the sun. Lindi watered it before opening her exercise book.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Which theme is most supportable from the short passage?","options":["Victory in a national election","Small acts of care amid neglect","The dangers of sea travel","Wealth guarantees happiness"],"correct_index":1,"explanation":"The dusty setting contrasts with Lindi's care for the living plant. A theme must be grounded in the actual details.","stimulus":"The classroom slept beneath a blanket of dust. At the window, one small plant leaned towards the sun. Lindi watered it before opening her exercise book.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Which evaluation best explains the effect of placing Lindi's action after the dust imagery?","options":["The watering proves the classroom has never been used.","The dust establishes that Lindi dislikes all plants.","The small act of watering offers a contrast to the room's apparent neglect.","The sequence proves every other learner is careless."],"correct_index":2,"explanation":"The blanket of dust suggests neglect, while watering sustains a living plant. Their juxtaposition creates a meaningful contrast without establishing everyone's motives.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"The classroom slept beneath a blanket of dust. At the window, one small plant leaned towards the sun. Lindi watered it before opening her exercise book."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Literary imagery and revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","enhl"],"metadata":{"term":4,"focus":"Literary imagery and revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Ll2-TaTJBoI%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"6b9a0f99-07f3-551d-8ab9-e730c9eeee8c","title":"Afrikaans HL · Grade 10 · Term 2: Leesbegrip en afleiding · Set A","subject":"Afrikaans HL","grade":"Grade 10","questions":[{"question":"Waar kom Lina aan?","options":["By die stasie","By die biblioteek","By die hospitaal","By die sportveld"],"correct_index":1,"explanation":"Die eerste sin noem die plek uitdruklik. Gebruik die teks as bewys vir 'n direkte begripsvraag.","stimulus":"Lina kom by die biblioteek aan toe die ligte reeds af is. Sy kyk na die boek in haar hand en dan na die geslote deur. Môre se toets voel skielik baie naby.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Watter besonderheid wys dat sy nie kan ingaan nie?","options":["Sy het 'n boek","Sy het môre 'n toets","Die deur is gesluit","Sy kyk na haar hand"],"correct_index":2,"explanation":"Die geslote deur verhinder toegang. Die ander besonderhede verduidelik nie waarom sy buite moet bly nie.","stimulus":"Lina kom by die biblioteek aan toe die ligte reeds af is. Sy kyk na die boek in haar hand en dan na die geslote deur. Môre se toets voel skielik baie naby.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Wat kan 'n mens redelikerwys oor Lina aflei?","options":["Sy het reeds die toets gedruip","Sy werk as bibliotekaris","Sy gaan beslis volpunte kry","Sy is bekommerd oor haar voorbereiding"],"correct_index":3,"explanation":"Die laaste sin suggereer bekommernis oor min tyd. Haar uiteindelike uitslag word nie gegee nie.","stimulus":"Lina kom by die biblioteek aan toe die ligte reeds af is. Sy kyk na die boek in haar hand en dan na die geslote deur. Môre se toets voel skielik baie naby.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Watter stelling word nie deur die teks ondersteun nie?","options":["Lina het die toets gedruip","Die ligte is af","Lina hou 'n boek vas","Die toets is môre"],"correct_index":0,"explanation":"Die uitslag verskyn nie in die teks nie. Moenie 'n moontlike vrees as 'n feit aanbied nie.","stimulus":"Lina kom by die biblioteek aan toe die ligte reeds af is. Sy kyk na die boek in haar hand en dan na die geslote deur. Môre se toets voel skielik baie naby.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Hoe beïnvloed die slotsin die betekenis van die geslote deur?","options":["Dit bewys dat Lina reeds gedruip het.","Dit wys dat daar geen boeke is nie.","Dit verbind die praktiese hindernis met Lina se groter toetsangs.","Dit bewys dat die toetsdatum verander het."],"correct_index":2,"explanation":"Die toets wat naby voel, beklemtoon dringendheid wanneer Lina nie kan ingaan nie. Die teks gee geen uitslag of verandering van die toetsdatum nie.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Lina kom by die biblioteek aan toe die ligte reeds af is. Sy kyk na die boek in haar hand en dan na die geslote deur. Môre se toets voel skielik baie naby."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Leesbegrip en afleiding. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","afhl"],"metadata":{"term":2,"focus":"Leesbegrip en afleiding","language":"af","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=LnUfxzL2B4A%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"ad85764e-5a3f-5b23-827f-d343f617b033","title":"Afrikaans HL · Grade 10 · Term 3: Oorreding en teikengehoor · Set A","subject":"Afrikaans HL","grade":"Grade 10","questions":[{"question":"Wat is die hoofdoel van die teks?","options":["Om 'n sportuitslag te gee","Om 'n eksamenrooster te publiseer","Om mense te oorreed om by die leeskring aan te sluit","Om 'n wetenskaplike proses te beskryf"],"correct_index":2,"explanation":"Die uitnodiging en positiewe belofte moedig deelname aan. Die doel is oorredend.","stimulus":"Kom Saterdag na ons leeskring! Bring een boek en neem 'n honderd idees huis toe. Almal is welkom, of jy vinnig lees of jou tyd neem.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Watter uitdrukking is 'n voorbeeld van oordrywing?","options":["Saterdag","een boek","leeskring","'n honderd idees"],"correct_index":3,"explanation":"Die groot getal beklemtoon die moontlike voordeel; dit is nie 'n gemete waarborg nie.","stimulus":"Kom Saterdag na ons leeskring! Bring een boek en neem 'n honderd idees huis toe. Almal is welkom, of jy vinnig lees of jou tyd neem.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Wat is die funksie van of jy vinnig lees of jou tyd neem?","options":["Dit stel lesers met verskillende leestempo's gerus","Dit sluit stadige lesers uit","Dit gee 'n statistiek","Dit verander die byeenkoms se datum"],"correct_index":0,"explanation":"Die inklusiewe formulering verlaag 'n moontlike hindernis tot deelname.","stimulus":"Kom Saterdag na ons leeskring! Bring een boek en neem 'n honderd idees huis toe. Almal is welkom, of jy vinnig lees of jou tyd neem.","cognitive_level":{"code":"L5","label":"Appreciation","band":"higher"}},{"question":"Watter werkwoord begin 'n bevelsin in die teks?","options":["Idees","Kom","Almal","Vinnig"],"correct_index":1,"explanation":"Kom spreek die leser direk aan en moedig optrede aan. Die onderwerp jy is geïmpliseer.","stimulus":"Kom Saterdag na ons leeskring! Bring een boek en neem 'n honderd idees huis toe. Almal is welkom, of jy vinnig lees of jou tyd neem.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Is 'n honderd idees hier 'n presiese waarborg? Kies die beste beoordeling.","options":["Ja; elke deelnemer kry presies honderd idees.","Nee; dit bewys dat niemand iets sal leer nie.","Nee; die oordrywing wek entoesiasme eerder as om 'n gemete uitkoms te belowe.","Ja; die teks gee 'n volledige telmetode."],"correct_index":2,"explanation":"Die oordrewe getal maak die uitnodiging aantreklik. Geen telmetode of waarborg word verskaf nie, dus moet die oorredende uitdrukking nie as 'n presiese meting gelees word nie.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Kom Saterdag na ons leeskring! Bring een boek en neem 'n honderd idees huis toe. Almal is welkom, of jy vinnig lees of jou tyd neem."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Oorreding en teikengehoor. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","afhl"],"metadata":{"term":3,"focus":"Oorreding en teikengehoor","language":"af","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=LnUfxzL2B4A%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"dd91bf7f-bd80-5465-87e4-15ab074cf87a","title":"Afrikaans HL · Grade 10 · Term 4: Beeldspraak en karakter · Set A","subject":"Afrikaans HL","grade":"Grade 10","questions":[{"question":"Watter frase bevat personifikasie?","options":["'n klein plant","haar oefenboek","by die venster","Die klaskamer slaap"],"correct_index":3,"explanation":"Die menslike handeling slaap word aan die klaskamer toegeken en skep 'n stil atmosfeer.","stimulus":"Die klaskamer slaap onder 'n kombers van stof. By die venster leun 'n klein plant na die son. Lindi gee dit water voordat sy haar oefenboek oopmaak.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Wat suggereer 'n kombers van stof?","options":["Stof bedek die oppervlaktes","Daar lê 'n letterlike wolkombers","Die klas is in die buitelug","Die son het verdwyn"],"correct_index":0,"explanation":"Die metafoor vergelyk die bedekking van stof met 'n kombers. Lees dit figuurlik.","stimulus":"Die klaskamer slaap onder 'n kombers van stof. By die venster leun 'n klein plant na die son. Lindi gee dit water voordat sy haar oefenboek oopmaak.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Watter handeling toon sorg?","options":["Die stof lê in die kamer","Lindi gee die plant water","Die venster bestaan","Die boek is toe"],"correct_index":1,"explanation":"Water gee ondersteun die plant se lewe en bied konkrete bewys van sorg.","stimulus":"Die klaskamer slaap onder 'n kombers van stof. By die venster leun 'n klein plant na die son. Lindi gee dit water voordat sy haar oefenboek oopmaak.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Watter tema word die beste deur die teks ondersteun?","options":["Oorwinning in 'n verkiesing","Die gevare van seereise","Klein dade van sorg te midde van verwaarlosing","Rykdom bring altyd geluk"],"correct_index":2,"explanation":"Die stowwerige ruimte kontrasteer met Lindi se sorg vir die plant. Die tema moet by die besonderhede pas.","stimulus":"Die klaskamer slaap onder 'n kombers van stof. By die venster leun 'n klein plant na die son. Lindi gee dit water voordat sy haar oefenboek oopmaak.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Wat is die uitwerking van Lindi se handeling ná die stofbeeld?","options":["Dit bewys dat niemand die klaskamer ooit gebruik het nie.","Dit bewys dat Lindi plante haat.","Die klein daad van sorg kontrasteer met die vertrek se oënskynlike verwaarlosing.","Dit toon dat elke ander leerder onverskillig is."],"correct_index":2,"explanation":"Die kombers van stof suggereer verwaarlosing, terwyl water die plant onderhou. Die teenstelling ondersteun 'n tema sonder om almal se motiewe te bewys.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Die klaskamer slaap onder 'n kombers van stof. By die venster leun 'n klein plant na die son. Lindi gee dit water voordat sy haar oefenboek oopmaak."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Beeldspraak en karakter. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","afhl"],"metadata":{"term":4,"focus":"Beeldspraak en karakter","language":"af","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=LnUfxzL2B4A%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"cd29f0cd-82c3-5841-9200-f6f1c4c3a454","title":"isiXhosa HL · Grade 10 · Term 2: Ukufunda ngengqiqo nokusebenzisa ubungqina · Set A","subject":"isiXhosa HL","grade":"Grade 10","questions":[{"question":"Kutheni uLutho esiya kwithala leencwadi?","options":["Ufuna ukuthengisa iincwadi.","Uya kudlala nabantakwabo.","Ufuna indawo ezolileyo yokufunda.","Usebenza apho ebusuku."],"correct_index":2,"explanation":"Isizathu sicaciswe kumazwi kaLutho: ufuna ukufunda kwindawo ezolileyo. Sebenzisa ubungqina obukwisicatshulwa.","stimulus":"ULutho ufika kwithala leencwadi emva kwesikolo. Uthi: Ndifuna indawo ezolileyo yokufunda kuba abantakwethu badlala ekhaya. Uphuma nencwadi enye aze abuye nayo ngoLwesihlanu.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Leliphi igama elibonisa ixesha lokufika kwakhe?","options":["Ekhaya","Incwadi","Abantakwethu","Emva kwesikolo"],"correct_index":3,"explanation":"Emva kwesikolo libonisa ixesha; ekhaya libonisa indawo. Funda umsebenzi wegama kwisivakalisi.","stimulus":"ULutho ufika kwithala leencwadi emva kwesikolo. Uthi: Ndifuna indawo ezolileyo yokufunda kuba abantakwethu badlala ekhaya. Uphuma nencwadi enye aze abuye nayo ngoLwesihlanu.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Siyintoni isizathu esinikwa ligama kuba?","options":["Abantakwabo bayadlala ekhaya.","Ithala livaliwe.","Ulahlekelwe yincwadi.","Ufuna ukulala."],"correct_index":0,"explanation":"Kuba lidibanisa into ayifunayo nesizathu sayo. Ingxolo yokudlala ichaza ukukhetha kwakhe ithala.","stimulus":"ULutho ufika kwithala leencwadi emva kwesikolo. Uthi: Ndifuna indawo ezolileyo yokufunda kuba abantakwethu badlala ekhaya. Uphuma nencwadi enye aze abuye nayo ngoLwesihlanu.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Leliphi ibango elingenabungqina kwisicatshulwa?","options":["ULutho uboleka incwadi enye.","ULutho ngoyena mfundi uphumelelayo esikolweni.","ULutho ufuna ukuzola.","ULutho ubuyisa incwadi ngoLwesihlanu."],"correct_index":1,"explanation":"Akukho manqaku okanye uthelekiso lwabafundi lunikiweyo. Musa ukongeza ingxelo engaxhaswanga sisicatshulwa.","stimulus":"ULutho ufika kwithala leencwadi emva kwesikolo. Uthi: Ndifuna indawo ezolileyo yokufunda kuba abantakwethu badlala ekhaya. Uphuma nencwadi enye aze abuye nayo ngoLwesihlanu.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Sesiphi isigqibo esilungileyo ngendlela isizathu sikaLutho esichazwe ngayo?","options":["Amazwi akhe angqina ukuba wonke umfundi unengxaki efanayo.","Ukufuna ukuthula kungqina ukuba akazithandi iincwadi.","Amazwi akhe asinika umbono wakhe, kodwa akangqini amava abo bonke abafundi.","Ukuboleka incwadi kungqina amanqaku akhe aphezulu."],"correct_index":2,"explanation":"ULutho uchaza imeko yakhe ekhaya nesidingo sakhe. Oko kusinceda simqonde, kodwa asikwazi ukwandisa loo mava kubo bonke abafundi ngaphandle kobunye ubungqina.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"ULutho ufika kwithala leencwadi emva kwesikolo. Uthi: Ndifuna indawo ezolileyo yokufunda kuba abantakwethu badlala ekhaya. Uphuma nencwadi enye aze abuye nayo ngoLwesihlanu."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Ukufunda ngengqiqo nokusebenzisa ubungqina. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","xhhl"],"metadata":{"term":2,"focus":"Ukufunda ngengqiqo nokusebenzisa ubungqina","language":"xh","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Iw2OEg6LMVY%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QsGQeCZMUxo%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/xhhl-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"c1db5d49-5401-5b18-88ac-3bcc87fbcef6","title":"isiXhosa HL · Grade 10 · Term 3: Intengiso, injongo nabaphulaphuli · Set A","subject":"isiXhosa HL","grade":"Grade 10","questions":[{"question":"Yintoni eyona njongo yale ntengiso?","options":["Kukuchaza indlela yokulungisa imoto.","Kukubala iindleko zepetroli.","Kukubalisa ngohambo oludlulileyo.","Kukukhuthaza abantu ukuba bajoyine iklabhu."],"correct_index":3,"explanation":"Isimemo kunye nomyalelo othi Joyina namhlanje zizixhobo zokukhuthaza umfundi ukuba enze into.","stimulus":"Intengiso ithi: Wamkelekile kwiklabhu yokufunda! Joyina namhlanje. Sabelana ngeencwadi simahla ngoLwesithathu. Le yeyona klabhu ibalaseleyo elizweni!","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Leliphi ibango elifuna ubungqina obungakumbi?","options":["Le yeyona klabhu ibalaseleyo elizweni.","Iintlanganiso zingoLwesithathu.","Kukho iincwadi ekwabelwana ngazo.","Intengiso imema amalungu."],"correct_index":0,"explanation":"Ukuthi yeyona ibalaseleyo kufuna imigaqo nothelekiso nezinye iiklabhu. Isibhengezo sodwa asibungqini obaneleyo.","stimulus":"Intengiso ithi: Wamkelekile kwiklabhu yokufunda! Joyina namhlanje. Sabelana ngeencwadi simahla ngoLwesithathu. Le yeyona klabhu ibalaseleyo elizweni!","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Igama simahla linokuba naliphi ifuthe?","options":["Liqinisekisa ukuba wonke umntu uya kupasa.","Linokutsala abafundi abangakwaziyo ukuhlawula.","Libonisa ukuba iklabhu ivaliwe.","Lithetha ukuba akukho ncwadi ikhoyo."],"correct_index":1,"explanation":"Ukungabikho kwentlawulo kunokwenza inkonzo ifikeleleke. Akuthembisi iziphumo zezifundo kumntu wonke.","stimulus":"Intengiso ithi: Wamkelekile kwiklabhu yokufunda! Joyina namhlanje. Sabelana ngeencwadi simahla ngoLwesithathu. Le yeyona klabhu ibalaseleyo elizweni!","cognitive_level":{"code":"L5","label":"Appreciation","band":"higher"}},{"question":"Ngowuphi umbuzo oluncedo ngaphambi kokujoyina?","options":["Ingaba zonke iincwadi zinombala omnye?","Ingaba intengiso iprintwe ngeyiphi inki?","Iphi indawo yentlanganiso kwaye iqala nini?","Ingaba onke amalungu anamagama afanayo?"],"correct_index":2,"explanation":"Indawo nexesha zizinto ezifunekayo ukuze umntu akwazi ukuya. Ulwazi aluchazwanga ngokupheleleyo kwintengiso.","stimulus":"Intengiso ithi: Wamkelekile kwiklabhu yokufunda! Joyina namhlanje. Sabelana ngeencwadi simahla ngoLwesithathu. Le yeyona klabhu ibalaseleyo elizweni!","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Ngaba ukususa ibango elithi yeyona klabhu ibalaseleyo kungasenza isimemo siphelele?","options":["Ewe; zonke iinkcukacha zokuhamba sele zinikiwe.","Hayi; isimemo ngasinye kufuneka sixoke.","Hayi; indawo nexesha lokuqala kusafuneka zicaciswe.","Ewe; igama simahla linika idilesi."],"correct_index":2,"explanation":"Ukususa ibango elingaxhaswanga kuphucula ukuthembeka, kodwa akuzalisi iinkcukacha ezishiyiweyo. Umfundi usafuna indawo nexesha ukuze acwangcise ukuya.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Intengiso ithi: Wamkelekile kwiklabhu yokufunda! Joyina namhlanje. Sabelana ngeencwadi simahla ngoLwesithathu. Le yeyona klabhu ibalaseleyo elizweni!"}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Intengiso, injongo nabaphulaphuli. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","xhhl"],"metadata":{"term":3,"focus":"Intengiso, injongo nabaphulaphuli","language":"xh","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Iw2OEg6LMVY%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QsGQeCZMUxo%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/xhhl-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"2a049548-81db-5836-9152-d3f12708a147","title":"isiXhosa HL · Grade 10 · Term 4: Imifanekiso-ngqondweni nomlinganiswa · Set A","subject":"isiXhosa HL","grade":"Grade 10","questions":[{"question":"Yeyiphi indlela yokusebenzisa ulwimi ekuthi ngathi ligubu?","options":["Isifaniso","Uluhlu","Umyalelo","Isibongozo"],"correct_index":0,"explanation":"Ngathi lithelekisa ukubetha kwentliziyo negubu. Isifaniso sisebenzisa uphawu lothelekiso olucacileyo.","stimulus":"Imvula ibetha ifestile. UNoma ubambe ileta engayivulanga. Uthe cwaka, ejonga endleleni. Intliziyo yakhe ibetha ngathi ligubu.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Yintoni esinokuyicingela ngokuthula nokubamba ileta?","options":["UNoma ngokuqinisekileyo uphumelele ibhaso.","UNoma usenokuba uxhalabile okanye ulindele okuthile.","UNoma uyayazi yonke into ezayo.","UNoma sele eyifundile ileta."],"correct_index":1,"explanation":"Ukuthula nokungayivuli ileta kunika umkhondo wexhala. Akuchazi ngokuqinisekileyo umxholo weleta.","stimulus":"Imvula ibetha ifestile. UNoma ubambe ileta engayivulanga. Uthe cwaka, ejonga endleleni. Intliziyo yakhe ibetha ngathi ligubu.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Leliphi ibango elichazwe ngokucacileyo?","options":["Ileta imxelela ukuba aphumelele.","Imvula iza kuphela ngomzuzu.","UNoma akakayivuli ileta.","UNoma ulinde udade wabo."],"correct_index":2,"explanation":"Amagama athi ileta engayivulanga abungqina obuthe ngqo. Amanye amabango ongeza ulwazi olunganikiweyo.","stimulus":"Imvula ibetha ifestile. UNoma ubambe ileta engayivulanga. Uthe cwaka, ejonga endleleni. Intliziyo yakhe ibetha ngathi ligubu.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Ngowuphi umhlathi wohlalutyo oqala kakuhle?","options":["Zonke iileta zizisa iindaba ezimbi.","UNoma ngumntu owoyikayo ngalo lonke ixesha.","Imvula ithetha ukuba ileta ayibalulekanga.","Ukuthelekiswa kwentliziyo negubu kugxininisa amandla eemvakalelo zikaNoma."],"correct_index":3,"explanation":"Impendulo edibanisa umzekelo wolwimi nentsingiselo yawo ixhaswa sisicatshulwa. Kuphephe ukwenza amabango apheleleyo angenabungqina.","stimulus":"Imvula ibetha ifestile. UNoma ubambe ileta engayivulanga. Uthe cwaka, ejonga endleleni. Intliziyo yakhe ibetha ngathi ligubu.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Uthelekiso lwentliziyo negubu lunegalelo lini kumoya wesicatshulwa?","options":["Lungqina ukuba kukho igubu lokwenene egumbini.","Lusixelela amanqaku akhe esikolo.","Lwenza iimvakalelo zivakale zinamandla, kodwa alusivezeli umxholo wencwadi.","Lungqina ukuba incwadi sele ivuliwe."],"correct_index":2,"explanation":"Uthelekiso lugxininisa ukubetha kwentliziyo nemvakalelo yexesha. Isiphumo solwimi siyavakala, kodwa iinkcukacha zencwadi azikachazwa.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Imvula ibetha ifestile. UNoma ubambe ileta engayivulanga. Uthe cwaka, ejonga endleleni. Intliziyo yakhe ibetha ngathi ligubu."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Imifanekiso-ngqondweni nomlinganiswa. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","xhhl"],"metadata":{"term":4,"focus":"Imifanekiso-ngqondweni nomlinganiswa","language":"xh","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Iw2OEg6LMVY%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QsGQeCZMUxo%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/xhhl-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"e7131a82-3eab-5fe4-97cf-94b5638bceab","title":"isiZulu HL · Grade 10 · Term 2: Ukufunda ngokuqonda nobufakazi · Set A","subject":"isiZulu HL","grade":"Grade 10","questions":[{"question":"Kungani uLindiwe eya emtatsheni wezincwadi?","options":["Ufuna ukuthengisa izincwadi.","Ufuna ukudlala nabafowabo.","Usebenza khona ebusuku.","Udinga indawo ethule yokufunda."],"correct_index":3,"explanation":"Isizathu sishiwo ngqo emazwini kaLindiwe. Sebenzisa ulwazi olusembhalweni ukuphendula.","stimulus":"ULindiwe uya emtatsheni wezincwadi ngemva kwesikole. Uthi: Ngidinga indawo ethule yokufunda ngoba abafowethu bayadlala ekhaya. Uboleka incwadi eyodwa ayibuyise ngoLwesihlanu.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Yimaphi amagama abonisa isikhathi sokufika kwakhe?","options":["Ngemva kwesikole","Ekhaya","Incwadi eyodwa","Abafowethu"],"correct_index":0,"explanation":"Ngemva kwesikole kubonisa isikhathi; ekhaya kubonisa indawo. Hlola umsebenzi wamagama emshweni.","stimulus":"ULindiwe uya emtatsheni wezincwadi ngemva kwesikole. Uthi: Ngidinga indawo ethule yokufunda ngoba abafowethu bayadlala ekhaya. Uboleka incwadi eyodwa ayibuyise ngoLwesihlanu.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Igama ngoba lethula luphi ulwazi?","options":["Igama lombhali wencwadi.","Isizathu sokufuna indawo ethule.","Inani lamakhasi.","Isikhathi sokuvala umtapo."],"correct_index":1,"explanation":"Ngoba lixhumanisa isidingo nesizathu: abafowabo bayadlala ekhaya.","stimulus":"ULindiwe uya emtatsheni wezincwadi ngemva kwesikole. Uthi: Ngidinga indawo ethule yokufunda ngoba abafowethu bayadlala ekhaya. Uboleka incwadi eyodwa ayibuyise ngoLwesihlanu.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Yisiphi isimangalo esingasekelwe yilo mbhalo?","options":["ULindiwe uboleka incwadi eyodwa.","ULindiwe ufuna ukuthula.","ULindiwe uhamba phambili ngamamaki esikoleni.","ULindiwe ubuyisa incwadi ngoLwesihlanu."],"correct_index":2,"explanation":"Umbhalo awunawo amamaki noma ukuqhathanisa abafundi. Ungangezi imininingwane enganikiwe.","stimulus":"ULindiwe uya emtatsheni wezincwadi ngemva kwesikole. Uthi: Ngidinga indawo ethule yokufunda ngoba abafowethu bayadlala ekhaya. Uboleka incwadi eyodwa ayibuyise ngoLwesihlanu.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Yisiphi isiphetho esifanele ngendlela isizathu sikaLindiwe esethulwa ngayo?","options":["Amazwi akhe afakazela ukuthi wonke umfundi unesimo esifanayo.","Ukufuna ukuthula kufakazela ukuthi akazithandi izincwadi.","Amazwi akhe aveza umbono wakhe, kodwa awafakazeli amava abo bonke abafundi.","Ukuboleka incwadi kufakazela amamaki akhe aphezulu."],"correct_index":2,"explanation":"ULindiwe uchaza isimo sakhe nesidingo sakhe. Lokhu kusisiza simqonde kodwa akusivumeli ukuthi siphethe ngamava abo bonke abafundi ngaphandle kobunye ubufakazi.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"ULindiwe uya emtatsheni wezincwadi ngemva kwesikole. Uthi: Ngidinga indawo ethule yokufunda ngoba abafowethu bayadlala ekhaya. Uboleka incwadi eyodwa ayibuyise ngoLwesihlanu."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Ukufunda ngokuqonda nobufakazi. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","zuhl"],"metadata":{"term":2,"focus":"Ukufunda ngokuqonda nobufakazi","language":"zu","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=LvpeV3dNO_0%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=nZlas4HGdYI%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/zuhl-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"2825f44e-ae66-5a3b-8975-416812ecd614","title":"isiZulu HL · Grade 10 · Term 3: Isikhangiso, inhloso nezethameli · Set A","subject":"isiZulu HL","grade":"Grade 10","questions":[{"question":"Iyini inhloso enkulu yesikhangiso?","options":["Ukukhuthaza abantu ukuba bajoyine ikilabhu.","Ukuchaza ukulungiswa kwemoto.","Ukubala izindleko zikaphethiloli.","Ukubika uhambo olwedlule."],"correct_index":0,"explanation":"Amagama athi Woza noJoyina akhuthaza umfundi ukuba athathe isinyathelo.","stimulus":"Isikhangiso sithi: Woza ekilabhini yokufunda! Joyina namuhla. Sabelana ngezincwadi mahhala ngoLwesithathu. Lena yikilabhu ehamba phambili ezweni!","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Yisiphi isimangalo esidinga obunye ubufakazi?","options":["Ukuhlangana kwenzeka ngoLwesithathu.","Lena yikilabhu ehamba phambili ezweni.","Kwabelwana ngezincwadi.","Isikhangiso simema amalungu."],"correct_index":1,"explanation":"Ukuthi ihamba phambili kudinga izindlela zokukala nokuqhathanisa namanye amakilabhu.","stimulus":"Isikhangiso sithi: Woza ekilabhini yokufunda! Joyina namuhla. Sabelana ngezincwadi mahhala ngoLwesithathu. Lena yikilabhu ehamba phambili ezweni!","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Igama mahhala lingaba namuphi umthelela?","options":["Liqinisekisa ukuthi wonke umuntu uyaphasa.","Lisho ukuthi ikilabhu ivaliwe.","Lingadonsa abafundi abangakwazi ukukhokha.","Lisho ukuthi azikho izincwadi."],"correct_index":2,"explanation":"Ukungakhokhi kungasiza ukufinyelela kule nkonzo. Akusona isiqinisekiso sempumelelo yomfundi ngamunye.","stimulus":"Isikhangiso sithi: Woza ekilabhini yokufunda! Joyina namuhla. Sabelana ngezincwadi mahhala ngoLwesithathu. Lena yikilabhu ehamba phambili ezweni!","cognitive_level":{"code":"L5","label":"Appreciation","band":"higher"}},{"question":"Yimuphi umbuzo owusizo ngaphambi kokujoyina?","options":["Zinombala munye yini zonke izincwadi?","Isikhangiso sinyatsheliswe ngayiphi inki?","Onke amalungu anegama elifanayo yini?","Iphi indawo yokuhlangana futhi kuqalwa nini?"],"correct_index":3,"explanation":"Indawo nesikhathi kuyadingeka ukuze umuntu akwazi ukuhlela ukuya. Le mininingwane ayiphelele esikhangisweni.","stimulus":"Isikhangiso sithi: Woza ekilabhini yokufunda! Joyina namuhla. Sabelana ngezincwadi mahhala ngoLwesithathu. Lena yikilabhu ehamba phambili ezweni!","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Ukususa isimangalo sokuthi yikilabhu ehamba phambili kwenza isimemo siphelele yini?","options":["Yebo; yonke imininingwane yokufika isivele ikhona.","Cha; zonke izimemo kufanele ziqambe amanga.","Cha; indawo nesikhathi sokuqala kusadinga ukucaciswa.","Yebo; igama mahhala linikeza ikheli."],"correct_index":2,"explanation":"Ukususa isimangalo esingenabufakazi kuthuthukisa ukwethembeka, kodwa akugcwalisi imininingwane eshiyiwe. Umfundi usadinga indawo nesikhathi ukuze ahlele ukuya.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Isikhangiso sithi: Woza ekilabhini yokufunda! Joyina namuhla. Sabelana ngezincwadi mahhala ngoLwesithathu. Lena yikilabhu ehamba phambili ezweni!"}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Isikhangiso, inhloso nezethameli. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","zuhl"],"metadata":{"term":3,"focus":"Isikhangiso, inhloso nezethameli","language":"zu","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=LvpeV3dNO_0%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=nZlas4HGdYI%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/zuhl-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"ae31cd75-8674-5d7f-9208-4ee872e4b2e4","title":"isiZulu HL · Grade 10 · Term 4: Izifenqo nomlingiswa · Set A","subject":"isiZulu HL","grade":"Grade 10","questions":[{"question":"Yisiphi isifenqo esisemagameni athi njengesigubhu?","options":["Uhlu","Isifaniso","Umyalelo","Isibingelelo"],"correct_index":1,"explanation":"Njenge kuqhathanisa ukushaya kwenhliziyo nesigubhu. Uphawu lokuqhathanisa lwenza lesi kube isifaniso.","stimulus":"Imvula ishaya iwindi. UNoma uphethe incwadi angakayivuli. Uthule ubheke emgwaqweni. Inhliziyo yakhe ishaya njengesigubhu.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Ukuthula kukaNoma kungasikisela ini?","options":["Ngokuqinisekile uwine umklomelo.","Wazi konke okuzokwenzeka.","Angase akhathazeke noma alindele okuthile.","Useyifundile incwadi."],"correct_index":2,"explanation":"Izenzo zinikeza umkhondo wemizwa kodwa azivezi okuqukethwe incwadi. Sebenzisa ulimi olungagabadeli ubufakazi.","stimulus":"Imvula ishaya iwindi. UNoma uphethe incwadi angakayivuli. Uthule ubheke emgwaqweni. Inhliziyo yakhe ishaya njengesigubhu.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Yiluphi ulwazi olushiwo ngokucacile?","options":["Incwadi imtshela ukuthi uphumelele.","Imvula izophela ngomzuzu.","UNoma ulinde udadewabo.","UNoma akakayivuli incwadi."],"correct_index":3,"explanation":"Amagama athi angakayivuli ayibufakazi obuqondile. Ezinye izimpendulo zengeza imininingwane.","stimulus":"Imvula ishaya iwindi. UNoma uphethe incwadi angakayivuli. Uthule ubheke emgwaqweni. Inhliziyo yakhe ishaya njengesigubhu.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Yisiphi isiqalo sokuhlaziya esisekelwe embhalweni?","options":["Ukuqhathanisa inhliziyo nesigubhu kugcizelela amandla emizwa kaNoma.","Zonke izincwadi ziletha izindaba ezimbi.","UNoma wesaba zonke izinto njalo.","Imvula isho ukuthi incwadi ayibalulekile."],"correct_index":0,"explanation":"Ukuhlaziya kuhlanganisa ubufakazi bolimi nencazelo yomsebenzi wabo embhalweni.","stimulus":"Imvula ishaya iwindi. UNoma uphethe incwadi angakayivuli. Uthule ubheke emgwaqweni. Inhliziyo yakhe ishaya njengesigubhu.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Ukuqhathanisa inhliziyo nesigubhu kunamuphi umthelela emoyeni wombhalo?","options":["Kufakazela ukuthi kukhona isigubhu sangempela egumbini.","Kusitshela amamaki akhe esikole.","Kwenza imizwa izwakale inamandla, kodwa akukuvezi okuqukethwe incwadi.","Kufakazela ukuthi incwadi isivuliwe."],"correct_index":2,"explanation":"Isifaniso sigcizelela ukushaya kwenhliziyo namandla omuzwa. Umthelela wolimi uyabonakala, kodwa okuqukethwe incwadi akukashiwo embhalweni.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Imvula ishaya iwindi. UNoma uphethe incwadi angakayivuli. Uthule ubheke emgwaqweni. Inhliziyo yakhe ishaya njengesigubhu."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Izifenqo nomlingiswa. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","zuhl"],"metadata":{"term":4,"focus":"Izifenqo nomlingiswa","language":"zu","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=LvpeV3dNO_0%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=nZlas4HGdYI%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/zuhl-10","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS language response: Barrett-informe